  renderTranscript();renderNextMoves();renderQuests();renderPresence();renderCharacter();renderCampaign();renderTimeline();renderGallery();renderSettings();renderAtmosphere();renderAI();renderMultiplayer();
  applyAtmosphere(state.atmosphere,{silent:true});
