// Atmosphere and adaptive effects -------------------------------------------------
let activeEffects=new Set();let fxParticles=[];let fxRAF=0;let shaderMode='none';let shaderRAF=0;let glState=null;
function mixHex(a,b,amount){const pa=hexRgb(a),pb=hexRgb(b),v=pa.map((x,i)=>Math.round(x+(pb[i]-x)*amount));return '#'+v.map(x=>x.toString(16).padStart(2,'0')).join('')}
function desiredTheme(id){const mode=state.ui.colorMode||'follow',src=THEMES[id]||THEMES.lantern;if(mode==='follow'||src.variant===mode)return src;const explicit={
  'default-dark':'default-light','default-light':'default-dark','ayu-dark':'ayu-light','ayu-light':'ayu-dark','rose-pine':'rose-pine-dawn','rose-pine-moon':'rose-pine-dawn','rose-pine-dawn':'rose-pine-moon',
  'catppuccin-mocha':'catppuccin-latte','catppuccin-macchiato':'catppuccin-latte','catppuccin-frappe':'catppuccin-latte','catppuccin-latte':'catppuccin-mocha',
  'nord-dark':'nord-light','nord-light':'nord-dark','gruvbox-dark':'gruvbox-light','gruvbox-light':'gruvbox-dark','tokyo-night':'tokyo-night-day','tokyo-night-storm':'tokyo-night-day','tokyo-night-day':'tokyo-night-storm',
  'everforest-dark':'everforest-light','everforest-light':'everforest-dark','kanagawa-dark':'kanagawa-light','kanagawa-light':'kanagawa-dark','kanagawa-wave':'kanagawa-lotus','kanagawa-lotus':'kanagawa-wave',
  'solarized-dark':'solarized-light','solarized-light':'solarized-dark','github-dark':'github-light','github-light':'github-dark','one-dark':'one-light','one-light':'one-dark','modus-vivendi':'modus-operandi','modus-operandi':'modus-vivendi',
  'serika-dark':'serika-light','serika-light':'serika-dark','whitesur-dark':'whitesur-light','whitesur-light':'whitesur-dark','graphite-dark':'graphite-light','graphite-light':'graphite-dark','night-owl':'night-owl-light','night-owl-light':'night-owl'
};const pair=THEMES[explicit[id]];if(pair&&pair.variant===mode)return pair;if(mode==='light')return {...src,name:src.name+' · light',variant:'light',bg:mixHex(src.bg,'#ffffff',.9),surface:mixHex(src.surface,'#ffffff',.82),surface2:mixHex(src.surface2,'#ffffff',.75),surface3:mixHex(src.surface3,'#ffffff',.67),ink:mixHex(src.ink,'#000000',.72),muted:mixHex(src.muted,'#333333',.55),accent:mixHex(src.accent,'#000000',.18)};return {...src,name:src.name+' · dark',variant:'dark',bg:mixHex(src.bg,'#000000',.82),surface:mixHex(src.surface,'#000000',.72),surface2:mixHex(src.surface2,'#000000',.62),surface3:mixHex(src.surface3,'#000000',.5),ink:mixHex(src.ink,'#ffffff',.72),muted:mixHex(src.muted,'#dddddd',.42),accent:mixHex(src.accent,'#ffffff',.12)}}
function applyTheme(id,transitionMs=1200){const t=desiredTheme(id);const root=document.documentElement;root.style.setProperty('--bg',t.bg);root.style.setProperty('--surface',t.surface);root.style.setProperty('--surface2',t.surface2);root.style.setProperty('--surface3',t.surface3);root.style.setProperty('--ink',t.ink);root.style.setProperty('--muted',t.muted);root.style.setProperty('--accent',t.accent);root.style.setProperty('--accent2',t.accent);root.style.colorScheme=t.variant==='light'?'light':'dark';document.querySelector('meta[name=theme-color]').content=t.bg;document.body.style.transition=`background-color ${transitionMs}ms ease,color ${transitionMs}ms ease`;}
function applyAtmosphere(atm,{silent=false}={}){applyTheme(atm.theme,atm.transition_ms||1200);const manual=state.ui.manualEffects||[];const effects=state.ui.effectsEnabled?[...(atm.effects||[]),...manual]:[];activeEffects=new Set(effects);$('lanternGlow').style.opacity=activeEffects.has('lantern')?Math.max(.15,atm.intensity||.25):0;shaderMode=activeEffects.has('underwater')?'underwater':activeEffects.has('water')?'water':activeEffects.has('aurora')?'aurora':'none';$('shaderCanvas').style.opacity=shaderMode==='none'?0:Math.min(.62,.18+(atm.intensity||.3));ensureEffectsLoop();ensureShaderLoop();if(!silent&&state.ui.motion)springPage();}
function toggleManualEffect(name){const a=state.ui.manualEffects;const i=a.indexOf(name);i>=0?a.splice(i,1):a.push(name);save();render();applyAtmosphere(state.atmosphere)}
function springPage(){if(!state.ui.motion)return;const el=document.querySelector('.view.active');if(!el)return;spring(el,{fromScale:.985,fromY:8,damping:20,stiffness:180})}
function spring(el,{fromScale=.96,fromY=12,stiffness=220,damping=18,mass=1}={}){if(!state.ui.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;let x=1-fromScale,y=fromY,vx=0,vy=0,last=performance.now();const step=(now)=>{const dt=Math.min(.032,(now-last)/1000);last=now;const ax=(-stiffness*x-damping*vx)/mass,ay=(-stiffness*y-damping*vy)/mass;vx+=ax*dt;vy+=ay*dt;x+=vx*dt;y+=vy*dt;el.style.transform=`translateY(${y}px) scale(${1-x})`;el.style.opacity=String(Math.min(1,1-Math.abs(x)*2));if(Math.abs(x)+Math.abs(y)+Math.abs(vx)+Math.abs(vy)>.015)requestAnimationFrame(step);else{el.style.transform='';el.style.opacity=''}};requestAnimationFrame(step)}
function effectBudget(){const mobile=innerWidth<700;const cores=navigator.hardwareConcurrency||4;return Math.max(20,Math.min(150,(mobile?45:90)+(cores-4)*8))*((state.ui.effectIntensity||35)/50)}
function ensureEffectsLoop(){if(fxRAF)return;const c=$('fxCanvas'),ctx=c.getContext('2d');let last=0;const loop=(ts)=>{fxRAF=requestAnimationFrame(loop);if(document.hidden||!state.ui.effectsEnabled||matchMedia('(prefers-reduced-motion: reduce)').matches)return;if(ts-last<16)return;last=ts;const dpr=Math.min(devicePixelRatio||1,innerWidth<700?1.2:1.6),w=innerWidth,h=innerHeight;if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);c.style.width=w+'px';c.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0)}ctx.clearRect(0,0,w,h);drawParticles(ctx,w,h,ts)};fxRAF=requestAnimationFrame(loop)}
function drawParticles(ctx,w,h,ts){const wants=[...activeEffects].filter(x=>['snow','rain','dust','embers','fireflies','bubbles','stars','fog','storm'].includes(x));if(!wants.length){fxParticles=[];return}const budget=Math.round(effectBudget());while(fxParticles.length<budget){const type=wants[Math.floor(Math.random()*wants.length)];fxParticles.push(newParticle(type,w,h))}while(fxParticles.length>budget)fxParticles.pop();for(const p of fxParticles){updateParticle(p,w,h);drawParticle(ctx,p,w,h,ts)}if(activeEffects.has('storm')&&Math.random()<.0015*(state.atmosphere.intensity+.2)){$('stormFlash').classList.remove('active');void $('stormFlash').offsetWidth;$('stormFlash').classList.add('active')}}
function newParticle(type,w,h){const base={type,x:Math.random()*w,y:Math.random()*h,z:Math.random(),vx:0,vy:0,size:1+Math.random()*3,life:Math.random()};if(type==='snow'){base.vx=-.2+Math.random()*.5;base.vy=.35+Math.random()*.6;base.size=1+Math.random()*3}else if(type==='rain'||type==='storm'){base.vx=-1-Math.random()*1.5;base.vy=8+Math.random()*9;base.size=8+Math.random()*14}else if(type==='dust'){base.vx=-.08+Math.random()*.16;base.vy=-.05+Math.random()*.1;base.size=.6+Math.random()*1.5}else if(type==='embers'){base.vx=-.15+Math.random()*.3;base.vy=-.4-Math.random()*.7;base.size=1+Math.random()*2}else if(type==='fireflies'){base.vx=-.2+Math.random()*.4;base.vy=-.2+Math.random()*.4;base.size=1.5+Math.random()*2}else if(type==='bubbles'){base.vx=-.15+Math.random()*.3;base.vy=-.4-Math.random()*.8;base.size=2+Math.random()*6}else if(type==='stars'){base.vx=base.vy=0;base.size=.5+Math.random()*1.6}else if(type==='fog'){base.vx=.08+Math.random()*.12;base.vy=0;base.size=90+Math.random()*160}return base}
function updateParticle(p,w,h){if(p.type==='fireflies'){p.vx+=(-.5+Math.random())*.012;p.vy+=(-.5+Math.random())*.012;p.vx*=.99;p.vy*=.99}p.x+=p.vx;p.y+=p.vy;p.life+=.005;if(p.x<-p.size*2||p.x>w+p.size*2||p.y<-p.size*2||p.y>h+p.size*2||p.life>1.6){Object.assign(p,newParticle(p.type,w,h));if(['embers','bubbles'].includes(p.type))p.y=h+10;if(['rain','storm','snow'].includes(p.type))p.y=-20}}
function drawParticle(ctx,p,w,h,ts){const a=Math.min(.7,state.atmosphere.intensity||.3);ctx.save();if(p.type==='snow'){ctx.fillStyle=`rgba(255,255,255,${a})`;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}else if(p.type==='rain'||p.type==='storm'){ctx.strokeStyle=`rgba(170,205,235,${a*.75})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-p.vx*2,p.y-p.size);ctx.stroke()}else if(p.type==='dust'){ctx.fillStyle=`rgba(230,205,165,${a*.34})`;ctx.fillRect(p.x,p.y,p.size,p.size)}else if(p.type==='embers'){ctx.shadowBlur=8;ctx.shadowColor='#ff8b38';ctx.fillStyle=`rgba(255,145,65,${a})`;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,6.28);ctx.fill()}else if(p.type==='fireflies'){const pulse=.3+.7*Math.sin(ts*.003+p.x);ctx.shadowBlur=12;ctx.shadowColor='#d6ff93';ctx.fillStyle=`rgba(205,255,130,${a*pulse})`;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,6.28);ctx.fill()}else if(p.type==='bubbles'){ctx.strokeStyle=`rgba(180,235,255,${a*.65})`;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,6.28);ctx.stroke()}else if(p.type==='stars'){const pulse=.3+.7*Math.abs(Math.sin(ts*.001+p.x));ctx.fillStyle=`rgba(255,255,255,${a*pulse})`;ctx.fillRect(p.x,p.y,p.size,p.size)}else if(p.type==='fog'){const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.size);g.addColorStop(0,`rgba(210,220,225,${a*.035})`);g.addColorStop(1,'rgba(210,220,225,0)');ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,6.28);ctx.fill()}ctx.restore()}
function ensureShaderLoop(){if(glState)return;const c=$('shaderCanvas'),gl=c.getContext('webgl',{alpha:true,antialias:false});if(!gl)return;const vs=`attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}`;const fs=`precision mediump float;uniform vec2 r;uniform float t;uniform float m;uniform vec3 a;float wave(vec2 p){return sin(p.x*8.+t)+sin(p.y*11.-t*1.2)+sin((p.x+p.y)*6.+t*.7);}void main(){vec2 uv=gl_FragCoord.xy/r;vec2 p=(uv-.5)*vec2(r.x/r.y,1.);vec3 col=vec3(0.);if(m<.5){col=vec3(0.);}else if(m<1.5){float w=wave(p);float shine=pow(max(0.,sin((p.x+w*.03)*22.+t*1.4)),8.);col=mix(vec3(.005,.04,.07),a*.45,.2+uv.y*.2)+shine*a*.35;}else if(m<2.5){float c1=abs(sin((p.x*7.+sin(p.y*5.+t))*2.));float c2=abs(sin((p.y*9.+sin(p.x*4.-t))*1.4));float ca=pow(max(0.,1.-abs(c1-c2)),7.);col=vec3(.0,.06,.09)+a*.12+ca*vec3(.1,.45,.5)*.5;}else{float band=sin(p.x*3.+sin(p.y*2.+t*.3)*2.+t*.2);float glow=pow(max(0.,band),4.)*(.4+.6*uv.y);col=a*glow*.45+vec3(.01,.02,.05);}gl_FragColor=vec4(col,clamp(length(col)*2.,0.,.75));}`;const sh=(type,src)=>{const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);return s};const pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,vs));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,fs));gl.linkProgram(pr);gl.useProgram(pr);const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);const loc=gl.getAttribLocation(pr,'p');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);glState={c,gl,pr,uR:gl.getUniformLocation(pr,'r'),uT:gl.getUniformLocation(pr,'t'),uM:gl.getUniformLocation(pr,'m'),uA:gl.getUniformLocation(pr,'a')};const loop=(ts)=>{shaderRAF=requestAnimationFrame(loop);if(document.hidden||shaderMode==='none'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const dpr=Math.min(devicePixelRatio||1,1.4),w=Math.round(innerWidth*dpr),h=Math.round(innerHeight*dpr);if(c.width!==w||c.height!==h){c.width=w;c.height=h;gl.viewport(0,0,w,h)}const mode=shaderMode==='water'?1:shaderMode==='underwater'?2:shaderMode==='aurora'?3:0;const rgb=hexRgb(desiredTheme(state.atmosphere.theme).accent);gl.uniform2f(glState.uR,w,h);gl.uniform1f(glState.uT,ts*.001);gl.uniform1f(glState.uM,mode);gl.uniform3f(glState.uA,rgb[0]/255,rgb[1]/255,rgb[2]/255);gl.drawArrays(gl.TRIANGLES,0,3)};shaderRAF=requestAnimationFrame(loop)}
function hexRgb(h){h=h.replace('#','');return [parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)]}
addEventListener('pointermove',e=>{document.documentElement.style.setProperty('--glow-x',`${(e.clientX/innerWidth)*100}%`);document.documentElement.style.setProperty('--glow-y',`${(e.clientY/innerHeight)*100}%`)},{passive:true});

// Local image store --------------------------------------------------------------
const assetUrls=new Map();let dbPromise=null;
function db(){if(!dbPromise)dbPromise=new Promise((res,rej)=>{const q=indexedDB.open('lantern-table-assets',2);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('assets'))q.result.createObjectStore('assets',{keyPath:'id'})};q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)});return dbPromise}
async function putAsset(blob,meta={}){const id=uid('asset'),rec={id,blob,meta,createdAt:Date.now()};const d=await db();await new Promise((res,rej)=>{const t=d.transaction('assets','readwrite');t.objectStore('assets').put(rec);t.oncomplete=res;t.onerror=()=>rej(t.error)});assetUrls.set(id,URL.createObjectURL(blob));state.assets.push({id,title:meta.title||'Campaign image',kind:meta.kind||'image',createdAt:rec.createdAt});save();render();return id}
async function loadAssetUrls(){const d=await db();const rows=await new Promise((res,rej)=>{const r=d.transaction('assets').objectStore('assets').getAll();r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});for(const r of rows){if(assetUrls.has(r.id))URL.revokeObjectURL(assetUrls.get(r.id));assetUrls.set(r.id,URL.createObjectURL(r.blob))}}
function getAssetUrl(id){return id?assetUrls.get(id)||'':null}
async function fileToAsset(file,title){if(!file)return;await putAsset(file,{title:title||file.name,kind:'upload'})}

// Drawing ------------------------------------------------------------------------
const draw={ctx:null,tool:'pen',drawing:false,history:[],last:null};
function initDraw(){const c=$('drawCanvas');draw.ctx=c.getContext('2d');c.addEventListener('pointerdown',e=>{if(rtc.role==='player'&&!state.campaign.permissions.playersDrawShared){toast('Host has locked shared drawing');return}draw.drawing=true;draw.last=canvasPos(c,e);c.setPointerCapture(e.pointerId);draw.history.push(draw.ctx.getImageData(0,0,c.width,c.height))});c.addEventListener('pointermove',e=>{if(!draw.drawing)return;const p=canvasPos(c,e),ctx=draw.ctx;ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=+$('brushSize').value*(c.width/c.clientWidth);ctx.strokeStyle=$('brushColor').value;ctx.globalCompositeOperation=draw.tool==='erase'?'destination-out':'source-over';ctx.beginPath();ctx.moveTo(draw.last.x,draw.last.y);ctx.lineTo(p.x,p.y);ctx.stroke();ctx.restore();draw.last=p});const stop=()=>draw.drawing=false;c.addEventListener('pointerup',stop);c.addEventListener('pointercancel',stop)}
function canvasPos(c,e){const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*(c.width/r.width),y:(e.clientY-r.top)*(c.height/r.height)}}
function resizeDrawCanvas(){/* fixed backing resolution preserves drawings; CSS handles display */}
$$('[data-draw-tool]').forEach(b=>b.onclick=()=>{draw.tool=b.dataset.drawTool;$$('[data-draw-tool]').forEach(x=>x.classList.toggle('active',x===b))});$('drawUndo').onclick=()=>{const img=draw.history.pop();if(img)draw.ctx.putImageData(img,0,0)};$('drawClear').onclick=()=>{draw.history.push(draw.ctx.getImageData(0,0,$('drawCanvas').width,$('drawCanvas').height));draw.ctx.clearRect(0,0,$('drawCanvas').width,$('drawCanvas').height)};$('drawSave').onclick=()=>{if(rtc.role==='player'&&!state.campaign.permissions.playersDrawShared)return toast('Host has locked shared drawing');$('drawCanvas').toBlob(async b=>{if(b){await putAsset(b,{title:`Drawing — ${state.scene.title}`,kind:'drawing'});addEvent('drawing','Saved a drawing');toast('Drawing saved locally')}},'image/png')};

// Audio --------------------------------------------------------------------------
const narrator={buffer:'',queue:Promise.resolve(),kokoro:null,kokoroLoading:null,voices:[],feed(delta){if(!state.audio.autoNarrate||state.audio.mode==='off')return;this.buffer+=delta;let m;while((m=this.buffer.match(/^([\s\S]*?[.!?](?:\s|$))/))&&m[1].trim().length>20){this.buffer=this.buffer.slice(m[1].length);this.speak(m[1].replace(/[#*_>`]/g,'').trim())}},flush(){const t=this.buffer.trim();this.buffer='';if(t)this.speak(t.replace(/[#*_>`]/g,''))},speak(text){if(!text)return;if(state.audio.mode==='system')speakSystem(text);else if(state.audio.mode==='kokoro')this.queue=this.queue.then(()=>speakKokoro(text)).catch(e=>{toast('Kokoro fallback: '+e.message);speakSystem(text)})}};
function voiceParams(){return {normal:{rate:1,pitch:1},creepy:{rate:.82,pitch:.62},ancient:{rate:.76,pitch:.78},urgent:{rate:1.18,pitch:.92}}[state.audio.style]||{rate:1,pitch:1}}
function speakSystem(text){if(!('speechSynthesis'in window))return;const u=new SpeechSynthesisUtterance(text),p=voiceParams(),voices=speechSynthesis.getVoices();u.rate=p.rate;u.pitch=p.pitch;u.volume=.9;u.voice=voices.find(v=>v.name===state.audio.voice)||voices.find(v=>v.localService)||voices[0]||null;speechSynthesis.speak(u)}
async function loadKokoro(){if(narrator.kokoro)return narrator.kokoro;if(narrator.kokoroLoading)return narrator.kokoroLoading;$('kokoroStatus').textContent='Loading Kokoro model locally… this can be a large first download.';narrator.kokoroLoading=(async()=>{const {KokoroTTS}=await import('https://cdn.jsdelivr.net/npm/kokoro-js@1.2.1/+esm');const device=('gpu'in navigator)?'webgpu':'wasm';const dtype=device==='webgpu'?'fp32':'q8';const tts=await KokoroTTS.from_pretrained('onnx-community/Kokoro-82M-v1.0-ONNX',{device,dtype,progress_callback:p=>{if(p?.progress!=null)$('kokoroStatus').textContent=`Downloading local voice model… ${Math.round(p.progress)}%`}});narrator.kokoro=tts;$('kokoroStatus').textContent=`Kokoro ready locally (${device}).`;return tts})();return narrator.kokoroLoading}
async function playKokoroBuffer(buffer){
  const Ctx=window.AudioContext||window.webkitAudioContext,ctx=new Ctx(),src=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),dry=ctx.createGain(),wet=ctx.createGain(),delay=ctx.createDelay(.6);
  const style=state.audio.style||'normal';src.buffer=buffer;filter.type='lowpass';filter.frequency.value=style==='creepy'?2900:style==='ancient'?4300:7600;dry.gain.value=1;wet.gain.value=style==='creepy'?.16:style==='ancient'?.10:.02;delay.delayTime.value=style==='creepy'?.075:style==='ancient'?.11:.025;
  src.connect(filter);filter.connect(dry);dry.connect(ctx.destination);filter.connect(delay);delay.connect(wet);wet.connect(ctx.destination);src.start();await new Promise(r=>src.onended=r);setTimeout(()=>ctx.close(),140)
}
async function speakKokoro(text){
  const tts=await loadKokoro(),p=voiceParams(),voice=state.audio.voice&&state.audio.voice.startsWith('a')?state.audio.voice:'am_adam',audio=await tts.generate(text,{voice,speed:p.rate});
  if(audio.toBlob){const blob=await audio.toBlob(),arr=await blob.arrayBuffer(),ctx=new (window.AudioContext||window.webkitAudioContext)(),buf=await ctx.decodeAudioData(arr.slice(0));await ctx.close();await playKokoroBuffer(buf);return}
  if(audio.audio&&audio.sampling_rate){const ctx=new (window.AudioContext||window.webkitAudioContext)(),buf=ctx.createBuffer(1,audio.audio.length,audio.sampling_rate);buf.copyToChannel(audio.audio,0);await ctx.close();await playKokoroBuffer(buf)}
}
function populateVoices(){if(!('speechSynthesis'in window))return;const voices=speechSynthesis.getVoices();const sel=$('voiceSelect');const names=voices.map(v=>v.name);const opts=[...names,'am_adam','am_michael','af_heart','af_bella'];sel.innerHTML=opts.map(n=>`<option ${state.audio.voice===n?'selected':''}>${esc(n)}</option>`).join('');if(!state.audio.voice&&opts[0])state.audio.voice=opts[0]}
if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=populateVoices;

// AI companion and streamed DM ---------------------------------------------------
let AI_BASE='';
async function getJSON(path,base=''){const r=await fetch(base+path,{cache:'no-store'});if(!r.ok)throw Error((await r.text()).slice(0,500));return r.json()}
async function bootConfig(){try{appConfig=await getJSON('/api/config')}catch{appConfig={mode:'standalone',companion_origin:'http://127.0.0.1:8765',signaling:false,multi_replica:false}}AI_BASE=appConfig.mode==='public'?appConfig.companion_origin:'';await probeCompanion(false)}
async function probeCompanion(show=true){try{const s=await getJSON('/api/session',AI_BASE);session={...session,...s};if(s.connected){try{const m=await getJSON('/api/models',AI_BASE);session.models=m.models||[];session.model=session.model||session.models[0]?.slug}catch{}}if(show)toast(s.connected?'Local AI companion connected':'Companion reachable; ChatGPT not connected')}catch(e){session.connected=false;if(show)toast('Local companion not reachable')}renderAI()}
async function streamPost(path,body,onEvent,signal,base=AI_BASE){const r=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal});if(!r.ok)throw Error((await r.text()).slice(0,900));const reader=r.body.getReader(),dec=new TextDecoder();let buf='';while(true){const {done,value}=await reader.read();if(done)break;buf+=dec.decode(value,{stream:true});let cut;while((cut=buf.indexOf('\n\n'))>=0){const block=buf.slice(0,cut);buf=buf.slice(cut+2);let event='message',data='';for(const line of block.split('\n')){if(line.startsWith('event:'))event=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim()}if(data){try{await onEvent(event,JSON.parse(data))}catch(e){console.error(e)}}}}}
async function act(text=$('action').value.trim(),{remoteActor=null}={}){if(!text||dmAborter)return;if(rtc.role==='player'){if(!rtc.sendHost({type:'player_action',text,actor:state.localPlayer.name,playerId:state.localPlayer.id})){toast('Host is offline — the campaign cannot advance');return}$('action').value='';toast('Action sent to host');return}const actor=remoteActor?.name||state.localPlayer.name;state.messages.push({id:uid('msg'),who:actor,kind:'player',text,at:nowISO()});addEvent('action',text,{actor,actorId:remoteActor?.id||state.localPlayer.id});$('action').value='';state.nextMoves=[];streamMessage={text:''};toolCards=[];dmAborter=new AbortController();$('stopStream').classList.remove('hidden');renderTranscript();rtc.broadcast({type:'player_action_echo',text,actor});try{await streamPost('/api/dm/stream',{model:session.model||null,campaign:state.campaign.name,campaign_settings:state.campaign.settings,scene:state.scene,characters:state.characters,quests:state.quests,inventory:state.inventory,timeline:state.timeline.slice(-30),journal:state.journal,messages:state.messages.slice(-24)},async(ev,d)=>{if(ev==='delta'){streamMessage.text+=d.delta;narrator.feed(d.delta);renderTranscript();rtc.broadcast({type:'dm_delta',delta:d.delta})}else if(ev==='tool'){handleTool(d.name,d.arguments);rtc.broadcast({type:'dm_tool',name:d.name,args:d.arguments})}else if(ev==='error')throw Error(d.message||'DM error');else if(ev==='done'){session.model=d.model||session.model}},dmAborter.signal);const final=streamMessage.text.trim();narrator.flush();if(final){state.messages.push({id:uid('msg'),who:'DM',kind:'dm',text:final,at:nowISO()});addEvent('dm','DM advanced the scene',{actor:'DM',actorId:null});rtc.broadcast({type:'dm_done',text:final})}streamMessage=null;save();render()}catch(e){if(e.name!=='AbortError')toast(e.message);streamMessage=null;renderTranscript()}finally{dmAborter=null;$('stopStream').classList.add('hidden')}}
function handleTool(name,a){if(name==='set_next_moves'){state.nextMoves=a.moves||[];renderNextMoves()}else if(name==='request_roll'){state.rollRequest=a;toolCards.push({kind:'roll',...a});renderTools()}else if(name==='render_card'){state.cards.push({...a,id:uid('card')});toolCards.push({kind:'card',...a});renderTools()}else if(name==='propose_state_patch'){toolCards.push({kind:'patch',...a});renderTools()}else if(name==='set_atmosphere'){if(state.ui.dmThemeControl){state.atmosphere={theme:a.theme,effects:(a.effects||[]).filter(x=>x!=='none'),intensity:a.intensity,reason:a.reason,transition_ms:a.transition_ms};applyAtmosphere(state.atmosphere);addEvent('atmosphere',`Atmosphere shifted: ${THEMES[a.theme]?.name||a.theme}`,{actor:'DM',actorId:null});save();render()}else toast(`DM suggested ${THEMES[a.theme]?.name||a.theme}; visual control is off`)}else if(name==='suggest_visual_prompt'){state.visualPrompts.push({id:uid('prompt'),kind:a.kind,title:a.title,prompt:a.prompt,aspect:a.suggested_aspect_ratio,at:nowISO()});addEvent('visual',`DM suggested art: ${a.title}`,{actor:'DM',actorId:null});save();render()}}
function renderTools(){$('toolShelf').innerHTML=toolCards.map((t,i)=>t.kind==='roll'?`<div class="tool-card"><div class="eyebrow">Roll requested</div><h4>${esc(t.label)}</h4><p>${esc(t.reason)} · ${esc(t.ability)} DC ${t.dc}</p><button class="button primary compact" data-tool-roll="${i}">Roll d20</button></div>`:t.kind==='patch'?`<div class="tool-card"><div class="eyebrow">State change</div><h4>${esc(t.reason)}</h4><p>${esc([t.scene_title,t.quest_title,t.loot_name].filter(Boolean).join(' · '))}</p><button class="button compact" data-patch="${i}">Apply</button></div>`:`<div class="tool-card"><div class="eyebrow">${esc(t.card_type)}</div><h4>${esc(t.title)}</h4><p>${esc(t.subtitle)}</p><div class="markdown">${markdown(t.markdown)}</div></div>`).join('');$$('[data-tool-roll]').forEach(b=>b.onclick=()=>performRoll(toolCards[+b.dataset.toolRoll]));$$('[data-patch]').forEach(b=>b.onclick=()=>applyPatch(toolCards[+b.dataset.patch]))}
function applyPatch(p){if(p.scene_title){state.scene.title=p.scene_title;state.scene.location=p.scene_title}if(p.scene_description)state.scene.text=p.scene_description;if(p.journal_append)state.journal+=(state.journal?'\n\n':'')+p.journal_append;if(p.hp_delta!=null)currentCharacter().hp=Math.max(0,Math.min(currentCharacter().maxHp,currentCharacter().hp+p.hp_delta));if(p.quest_title){const q=state.quests.find(q=>q.title===p.quest_title);q?q.note=p.quest_note:state.quests.push({title:p.quest_title,note:p.quest_note||''})}if(p.loot_name)state.inventory.push({name:p.loot_name,description:p.loot_description||''});addEvent('state',p.reason,{actor:'DM',actorId:null});save();render();toast('Campaign updated')}
function rollDie(sides,label=`d${sides}`){const value=1+Math.floor(Math.random()*sides);addEvent('roll',`${label}: ${value}`);state.messages.push({id:uid('msg'),who:state.localPlayer.name,kind:'player',text:`🎲 ${label}: **${value}**`,at:nowISO()});save();render();toast(`${label}: ${value}`);return value}
function performRoll(req){const d=rollDie(20,`${req.ability} check`),c=currentCharacter(),mods={STR:0,DEX:2,CON:0,INT:0,WIS:1,CHA:0,NONE:0};const total=d+(mods[req.ability]||0);toolCards=[];state.messages.push({id:uid('msg'),who:'System',kind:'player',text:`${req.label}: ${d} + ${mods[req.ability]||0} = ${total} vs DC ${req.dc} — ${total>=req.dc?'success':'failure'}`,at:nowISO()});save();render();setTimeout(()=>act(`Roll result for ${req.label}: ${total} against DC ${req.dc} (${total>=req.dc?'success':'failure'}). Continue from that result.`),80)}
function chooseMove(i){const m=state.nextMoves[i];if(m)act(m.action)}

// WebRTC host-star multiplayer ---------------------------------------------------
const rtc={
  role:'solo',ws:null,room:'',peers:{},pc:null,dc:null,
  iceServers:[{urls:['stun:stun.cloudflare.com:3478']}],connected:false,retry:null,hostUnavailable:false,localCharacterDraft:null,
  async loadIce(){try{const d=await getJSON('/api/ice');this.iceServers=d.iceServers||this.iceServers}catch{}},
  async startHost(room){
    this.leave(false);await this.loadIce();this.role='host';this.room=room;this.hostUnavailable=false;
    state.multiplayer.role='host';state.multiplayer.lastRoom=room;save({broadcast:false});this.connectSignal();render();toast(`Hosting ${room}`)
  },
  async join(room){
    this.localCharacterDraft=clone(currentCharacter());this.leave(false);await this.loadIce();this.role='player';this.room=room.toUpperCase();this.hostUnavailable=false;
    state.multiplayer.role='player';state.multiplayer.lastRoom=this.room;save({broadcast:false});this.connectSignal();render()
  },
  connectSignal(){
    if(!appConfig.signaling||this.role==='solo'||[0,1].includes(this.ws?.readyState))return;
    const scheme=location.protocol==='https:'?'wss':'ws';
    const ws=new WebSocket(`${scheme}://${location.host}/ws/room/${encodeURIComponent(this.room)}/${encodeURIComponent(state.localPlayer.id)}?role=${this.role}`);
    this.ws=ws;
    ws.onopen=()=>{this.connected=true;this.hostUnavailable=false;render();if(this.role==='player')this.signal('*','hello',{name:state.localPlayer.name,character:(this.localCharacterDraft||currentCharacter()).name})};
    ws.onmessage=e=>{try{this.onSignal(JSON.parse(e.data))}catch(err){console.error(err)}};
    ws.onclose=e=>{
      this.connected=false;render();
      if(this.role!=='solo'&&e.code!==1000){clearTimeout(this.retry);const wait=this.hostUnavailable?15000:900+Math.random()*900;this.retry=setTimeout(()=>this.connectSignal(),wait)}
    }
  },
  signal(target,type,payload){if(this.ws?.readyState===1)this.ws.send(JSON.stringify({type,target,payload:{kind:type,...payload}}))},
  async onSignal(msg){
    if(msg.type==='server_draining'){setTimeout(()=>{try{this.ws?.close(1012,'reconnect')}catch{}},120);return}
    if(msg.type==='host_offline'){
      const first=!this.hostUnavailable;this.hostUnavailable=true;this.connected=false;state.multiplayer.hostOnline=false;render();
      if(first)toast('Host is offline — campaign stays read-only until they return');return
    }
    if(msg.type==='presence'){
      if(msg.event==='joined'&&this.role==='host'&&msg.role==='player')setTimeout(()=>this.makeOffer(msg.sender),120);
      if(msg.event==='left')this.closePeer(msg.sender);render();return
    }
    const p=msg.payload||{};
    if(p.kind==='hello'&&this.role==='host')await this.makeOffer(msg.sender,p);
    else if(p.kind==='offer'&&this.role==='player')await this.acceptOffer(msg.sender,p);
    else if(p.kind==='answer'&&this.role==='host'){const peer=this.peers[msg.sender];if(peer)await peer.pc.setRemoteDescription(p.sdp)}
    else if(p.kind==='ice'){const target=this.role==='host'?this.peers[msg.sender]?.pc:this.pc;try{if(target&&p.candidate)await target.addIceCandidate(p.candidate)}catch{}}
  },
  async makeOffer(peerId,hello={}){
    if(this.peers[peerId])return;
    const pc=new RTCPeerConnection({iceServers:this.iceServers}),dc=pc.createDataChannel('lantern',{ordered:true});
    this.peers[peerId]={pc,dc,name:hello.name||'Player',character:hello.character||'',role:'player'};this.setupPC(pc,peerId);this.setupDC(dc,peerId);
    const offer=await pc.createOffer();await pc.setLocalDescription(offer);this.signal(peerId,'offer',{sdp:pc.localDescription})
  },
  async acceptOffer(hostId,p){
    const pc=new RTCPeerConnection({iceServers:this.iceServers});this.pc=pc;this.setupPC(pc,hostId);pc.ondatachannel=e=>{this.dc=e.channel;this.setupDC(this.dc,hostId)};
    await pc.setRemoteDescription(p.sdp);const ans=await pc.createAnswer();await pc.setLocalDescription(ans);this.signal(hostId,'answer',{sdp:pc.localDescription})
  },
  setupPC(pc,peerId){
    pc.onicecandidate=e=>{if(e.candidate)this.signal(peerId,'ice',{candidate:e.candidate})};
    pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState)){if(this.role==='player'){this.connected=false;state.multiplayer.hostOnline=false;render()}else this.closePeer(peerId)}}
  },
  setupDC(dc,peerId){
    dc.onopen=()=>{
      this.connected=true;this.hostUnavailable=false;state.multiplayer.hostOnline=true;
      if(this.role==='host'){
        const p=this.peers[peerId];dc.send(JSON.stringify({type:'snapshot',state:sanitizedState()}));dc.send(JSON.stringify({type:'peer_info',name:state.localPlayer.name,character:currentCharacter().name}));if(p)toast(`${p.name||'A player'} joined the table`)
      }else{
        dc.send(JSON.stringify({type:'peer_info',name:state.localPlayer.name,character:(this.localCharacterDraft||currentCharacter()).name}));toast('Connected to host')
      }
      render()
    };
    dc.onmessage=e=>{try{this.onData(JSON.parse(e.data),peerId)}catch(err){console.error(err)}};
    dc.onclose=()=>{if(this.role==='player'){this.connected=false;state.multiplayer.hostOnline=false;render()}else this.closePeer(peerId)}
  },
  onData(m,peerId){
    if(this.role==='host'){
      if(m.type==='peer_info'){Object.assign(this.peers[peerId]||{},m);renderPresence()}
      else if(m.type==='player_action'){const peer=this.peers[peerId]||{};if(!dmAborter)act(m.text,{remoteActor:{name:m.actor||peer.name||'Player',id:peerId}})}
      else if(m.type==='character_claim'&&m.playerId===peerId){
        let ch=state.characters.find(c=>c.ownerPlayerId===peerId);
        if(!ch){const src=m.character||{};ch={id:uid('char'),ownerPlayerId:peerId,name:String(src.name||'New Adventurer').slice(0,80),class:String(src.class||'Adventurer').slice(0,80),level:+src.level||1,ac:+src.ac||10,hp:+src.hp||10,maxHp:+src.maxHp||10,notes:String(src.notes||'').slice(0,5000),location:state.scene.location,portraitAssetId:null};state.characters.push(ch);addEvent('character',`${ch.name} joined the party`,{actor:ch.name,actorId:peerId,location:ch.location});save();render()}
      }
      else if(m.type==='character_patch'&&m.playerId===peerId){const ch=state.characters.find(c=>c.ownerPlayerId===peerId);if(ch&&state.campaign.permissions.playersEditOwnCharacter){Object.assign(ch,m.patch);addEvent('character',`${ch.name} updated their character`,{actor:ch.name,actorId:peerId,location:ch.location});save();render()}}
    }else{
      if(m.type==='snapshot'){
        const draft=clone(this.localCharacterDraft||currentCharacter());const localPrefs={ui:state.ui,audio:state.audio,localPlayer:state.localPlayer,multiplayer:state.multiplayer};
        state=mergeDefaults(defaults,m.state);Object.assign(state,localPrefs);state.multiplayer.role='player';state.multiplayer.hostOnline=true;
        let owned=state.characters.find(c=>c.ownerPlayerId===state.localPlayer.id);
        if(!owned){owned={...draft,id:uid('char'),ownerPlayerId:state.localPlayer.id,location:state.scene.location};state.characters.push(owned);this.sendHost({type:'character_claim',playerId:state.localPlayer.id,character:owned})}
        else if(draft&&state.campaign.permissions.playersEditOwnCharacter){const patch={name:draft.name,class:draft.class,level:draft.level,ac:draft.ac,hp:draft.hp,maxHp:draft.maxHp,notes:draft.notes};Object.assign(owned,patch);this.sendHost({type:'character_patch',playerId:state.localPlayer.id,patch})}
        state.localPlayer.characterId=owned.id;this.localCharacterDraft=clone(owned);save({broadcast:false});render()
      }
      else if(m.type==='player_action_echo'){state.messages.push({id:uid('msg'),who:m.actor||'Player',kind:'player',text:m.text||'',at:nowISO()});addEvent('action',m.text||'',{actor:m.actor||'Player',actorId:null});save({broadcast:false});render()}
      else if(m.type==='dm_delta'){if(!streamMessage)streamMessage={text:''};streamMessage.text+=m.delta;narrator.feed(m.delta);renderTranscript()}
      else if(m.type==='dm_done'){streamMessage=null;state.messages.push({id:uid('msg'),who:'DM',kind:'dm',text:m.text,at:nowISO()});narrator.flush();save({broadcast:false});render()}
      else if(m.type==='dm_tool')handleTool(m.name,m.args)
      else if(m.type==='peer_info'){this.peers[peerId]={name:m.name,character:m.character,role:'host'};renderPresence()}
    }
  },
  broadcast(m){if(this.role!=='host')return;for(const p of Object.values(this.peers))if(p.dc?.readyState==='open')p.dc.send(JSON.stringify(m))},
  sendHost(m){if(this.role==='player'&&this.dc?.readyState==='open'){this.dc.send(JSON.stringify(m));return true}return false},
  closePeer(id){const p=this.peers[id];if(p){try{p.pc.close()}catch{}delete this.peers[id]}renderPresence()},
  leave(update=true){clearTimeout(this.retry);try{this.ws?.close(1000)}catch{}try{this.pc?.close()}catch{}for(const p of Object.values(this.peers))try{p.pc.close()}catch{}this.ws=null;this.pc=null;this.dc=null;this.peers={};this.role='solo';this.connected=false;this.hostUnavailable=false;if(update){state.multiplayer.role='solo';save({broadcast:false});render()}}
};
function openJoinPrompt(){const code=prompt('Join code',state.multiplayer.lastRoom||'');if(code)rtc.join(code.trim())}

// Campaign wizard ----------------------------------------------------------------
let selectedPreset='heroic';
function initWizard(){$('presetGrid').innerHTML=Object.entries(PRESETS).map(([id,p])=>`<button class="preset ${id===selectedPreset?'selected':''}" data-preset="${id}"><span class="preset-icon">${p.icon}</span><b>${p.name}</b><span>${p.desc}</span></button>`).join('');$$('[data-preset]').forEach(b=>b.onclick=()=>{selectedPreset=b.dataset.preset;$$('[data-preset]').forEach(x=>x.classList.toggle('selected',x===b));const p=PRESETS[selectedPreset];$('wizDifficulty').value=p.settings.difficulty;$('wizRules').value=p.settings.rules;$('wizDm').value=p.settings.dmStyle;$('wizDesc').value=p.settings.description;$('wizChar').value='Quick'});$('wizName').value=state.campaign.name}
function startWizard(){const p=PRESETS[selectedPreset];state.campaign.name=$('wizName').value.trim()||p.name;state.campaign.preset=selectedPreset;state.campaign.started=true;state.campaign.settings={...p.settings,difficulty:$('wizDifficulty').value,rules:$('wizRules').value,dmStyle:$('wizDm').value,description:$('wizDesc').value,characterCreation:$('wizChar').value};state.atmosphere={...p.atmosphere,reason:`${p.name} opening`};state.prep={nearbyLocations:'deferred',importantNPCs:'deferred',rumors:'deferred',firstEncounter:'deferred'};addEvent('campaign',`Started ${p.name} preset`,{actor:'Host'});save();render();applyAtmosphere(state.atmosphere);toast('Campaign opened — play now, refine later')}

// Bindings -----------------------------------------------------------------------
$('wizardStart').onclick=startWizard;$('reopenWizard').onclick=()=>{$('wizard').classList.remove('hidden');initWizard()};$('journal').oninput=e=>{if(canHostEdit()){state.journal=e.target.value;save()}};$('send').onclick=()=>act();$('action').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();act()}};$('stopStream').onclick=()=>dmAborter?.abort();
[4,6,8,10,12,20,100].forEach(n=>{const b=document.createElement('button');b.className='die';b.textContent='d'+n;b.onclick=()=>rollDie(n);$('diceStrip').append(b)});
$('themeQuick').onclick=()=>$('themeSheet').classList.remove('hidden');$('tableQuick').onclick=()=>{renderTableSheet();$('tableSheet').classList.remove('hidden')};$$('[data-close-sheet]').forEach(e=>e.onclick=closeSheets);function closeSheets(){$$('.bottom-sheet').forEach(s=>s.classList.add('hidden'))}
function renderTableSheet(){$('tableSheetBody').innerHTML=`<p><b>Campaign code: ${esc(state.campaign.joinCode)}</b></p><p class="muted">Host must be online for canonical play. Returning players can reuse this code in a future session.</p><div class="button-row"><button class="button primary" id="sheetHost">Host</button><button class="button" id="sheetJoin">Join</button><button class="button" id="sheetCopy">Copy invite</button></div>`;$('sheetHost').onclick=()=>{rtc.startHost(state.campaign.joinCode);closeSheets()};$('sheetJoin').onclick=()=>{openJoinPrompt();closeSheets()};$('sheetCopy').onclick=copyInvite}
function copyInvite(){const url=`${location.origin}${location.pathname}#join=${state.campaign.joinCode}`;navigator.clipboard.writeText(url);toast('Invite copied')}$('copyInvite').onclick=copyInvite;
$('colorMode').onchange=e=>{state.ui.colorMode=e.target.value;save();applyAtmosphere(state.atmosphere);render()};$('themeSelect').onchange=e=>{state.atmosphere.theme=e.target.value;state.atmosphere.reason='Player-selected theme';save();applyAtmosphere(state.atmosphere);render()};$('dmThemeToggle').onchange=e=>{state.ui.dmThemeControl=e.target.checked;save()};$('effectsToggle').onchange=e=>{state.ui.effectsEnabled=e.target.checked;save();applyAtmosphere(state.atmosphere)};$('motionToggle').onchange=e=>{state.ui.motion=e.target.checked;save()};$('effectIntensity').oninput=e=>{state.ui.effectIntensity=+e.target.value;save();applyAtmosphere(state.atmosphere)};
$('voiceMode').onchange=async e=>{state.audio.mode=e.target.value;save();if(e.target.value==='kokoro'){try{await loadKokoro()}catch(err){toast('Kokoro could not load; system voice still works')}}renderSettings()};$('voiceSelect').onchange=e=>{state.audio.voice=e.target.value;save()};$('voiceStyle').onchange=e=>{state.audio.style=e.target.value;save()};$('autoNarrate').onchange=e=>{state.audio.autoNarrate=e.target.checked;save()};$('testVoice').onclick=()=>narrator.speak('The lantern flickers. Something on the other side of the door has started breathing.');$('audioQuick').onclick=()=>{if(state.audio.mode==='off'){state.audio.mode='system';state.audio.autoNarrate=true;toast('Narration on')}else{state.audio.autoNarrate=!state.audio.autoNarrate;toast(state.audio.autoNarrate?'Narration on':'Narration paused')}save();renderSettings()};
$('setPortrait').onclick=()=>{if(rtc.role==='player'&&!state.campaign.permissions.playersChangePortrait)return toast('Host has locked portrait changes');$('portraitUpload').click()};$('portraitUpload').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(rtc.role==='player'&&!state.campaign.permissions.playersChangePortrait)return toast('Host has locked portrait changes');const id=await putAsset(f,{title:`${currentCharacter().name} portrait`,kind:'portrait'});currentCharacter().portraitAssetId=id;rtc.localCharacterDraft=clone(currentCharacter());save({broadcast:rtc.role!=='player'});render()};$('imageUpload').onchange=async e=>{const f=e.target.files[0];if(f)await fileToAsset(f)};
function editCharacter(key,val){const c=currentCharacter();if(rtc.role==='player'&&!state.campaign.permissions.playersEditOwnCharacter)return toast('Host has locked character edits');c[key]=['level','ac','hp','maxHp'].includes(key)?+val:val;addEvent('character',`${c.name} updated ${key}`,{actor:c.name,actorId:state.localPlayer.id,location:c.location});if(rtc.role==='player'){rtc.localCharacterDraft=clone(c);rtc.sendHost({type:'character_patch',playerId:state.localPlayer.id,patch:{[key]:c[key]}})}save({broadcast:rtc.role!=='player'});render()}
$$('[data-timeline-mode]').forEach(b=>b.onclick=()=>{timelineMode=b.dataset.timelineMode;$$('[data-timeline-mode]').forEach(x=>x.classList.toggle('active',x===b));renderTimeline()});
$('exportSave').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${state.campaign.name.replace(/\W+/g,'-').toLowerCase()}.lantern.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('exportPlayerPass').onclick=()=>{const pass={version:1,kind:'lantern-player-pass',player:{id:state.localPlayer.id,name:state.localPlayer.name},character:currentCharacter()};const blob=new Blob([JSON.stringify(pass,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${(currentCharacter().name||'player').replace(/\W+/g,'-').toLowerCase()}.lantern-player.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('importPlayerPass').onchange=async e=>{try{const j=JSON.parse(await e.target.files[0].text());if(j.kind!=='lantern-player-pass'||!j.player?.id)throw Error('Not a Lantern Table Player Pass');localStorage.setItem(PLAYER_KEY,j.player.id);state.localPlayer.id=j.player.id;state.localPlayer.name=j.player.name||state.localPlayer.name;if(j.character){let ch=state.characters.find(c=>c.ownerPlayerId===j.player.id);if(!ch){ch={...j.character,id:j.character.id||uid('char'),ownerPlayerId:j.player.id};state.characters.push(ch)}else Object.assign(ch,j.character,{ownerPlayerId:j.player.id});state.localPlayer.characterId=ch.id}save({broadcast:false});toast('Player Pass imported — future reconnects use this identity');render()}catch(err){toast('Player Pass import failed: '+err.message)}};$('importSave').onchange=async e=>{try{const j=JSON.parse(await e.target.files[0].text());state=mergeDefaults(defaults,j);save({broadcast:false});render();toast('Campaign imported')}catch(err){toast('Import failed: '+err.message)}};$('resetSave').onclick=()=>{if(confirm('Reset this local campaign?')){localStorage.removeItem(STORAGE_KEY);location.reload()}};

// Startup ------------------------------------------------------------------------
(async()=>{initWizard();initDraw();await loadAssetUrls().catch(()=>{});await bootConfig();const hash=new URLSearchParams(location.hash.slice(1));if(hash.get('join'))setTimeout(()=>rtc.join(hash.get('join')),500);render();applyAtmosphere(state.atmosphere,{silent:true});if(state.campaign.started&&state.multiplayer.lastRoom&&appConfig.signaling){const previousRole=state.multiplayer.role;if(previousRole==='host')setTimeout(()=>rtc.startHost(state.multiplayer.lastRoom),350);else if(previousRole==='player')setTimeout(()=>rtc.join(state.multiplayer.lastRoom),500)}})();
